// Isolated UI fixture. Never contacts APIs, imports business data, or confirms warehouse records.
import {useState} from 'react';
import {createRoot} from 'react-dom/client';
import ProductionReportDayReview from '../../components/production-report-day-review';
import {order,employees,reports as initial} from './report-review-data.mjs';
import '../../app/production-management.css';
function Fixture(){const [reports,setReports]=useState<any[]>(initial),[manager,setManager]=useState(true),[calls,setCalls]=useState(0),[partial,setPartial]=useState(false);return <main className="app-shell" style={{fontFamily:'Times New Roman',padding:12,maxWidth:'100%',boxSizing:'border-box'}}><h1>TEST · Tiến độ sản xuất</h1><p>Dữ liệu tổng hợp, không gọi API / kho.</p><button onClick={()=>setManager(x=>!x)}>Đổi quyền</button><button onClick={()=>setReports(old=>[...old,{...initial[0],id:'TEST-NEW',productionDate:'2026-10-25',hours:null}])}>Thêm ngày có cảnh báo</button><button onClick={()=>setReports(old=>old.map(r=>({...r,version:r.version+1})))}>Mô phỏng dữ liệu đổi</button><label><input type="checkbox" checked={partial} onChange={e=>setPartial(e.target.checked)}/>Mô phỏng lỗi một phần</label><p id="fixture-calls">Số phiếu gửi: {calls}</p><section className="production-workspace"><ProductionReportDayReview order={order} reports={reports} sourceReports={reports} employees={employees} manager={manager} busy={false} t={s=>s} open={r=>window.alert(`${r.id}: HC ${r.hours?.hc??'—'}, TC ${r.hours?.ot??'—'}`)} onConfirm={async items=>{setCalls(n=>n+items.length);await new Promise(resolve=>setTimeout(resolve,30));const results=items.map((item,i)=>({id:item.report.id,ok:!(partial&&i===0),error:partial&&i===0?'Lỗi TEST':undefined}));setReports(old=>old.map(r=>results.some(x=>x.id===r.id&&x.ok)?{...r,reviewStatus:'Đã xác nhận',reviewedBy:'TEST',reviewedAt:'2026-10-28T10:00:00+07:00'}:r));return {results};}}/></section></main>};createRoot(document.getElementById('root')!).render(<Fixture/>);
